def merge_max(d1, d2):
    res = dict(d1)
    for k, v in d2.items():
        if k in res:
            res[k] = max(res[k], v)
        else:
            res[k] = v
    return res

def deep_merge(d1, d2):
    res = dict(d1)
    for k, v in d2.items():
        if k in res and isinstance(res[k], dict) and isinstance(v, dict):
            res[k] = deep_merge(res[k], v)
        else:
            res[k] = v
    return res

def grade_distribution(scores):
    d = {"A": 0, "B": 0, "C": 0, "D": 0, "F": 0}
    for s in scores:
        if s >= 90:
            d["A"] += 1
        elif s >= 80:
            d["B"] += 1
        elif s >= 70:
            d["C"] += 1
        elif s >= 60:
            d["D"] += 1
        else:
            d["F"] += 1
    return d

def weighted_average(values, weights):
    total_weight = sum(weights[k] for k in values)
    if total_weight == 0:
        return 0.0
    return sum(values[k] * weights[k] for k in values) / total_weight

def jaccard_similarity_keys(a, b):
    ka = set(a.keys())
    kb = set(b.keys())
    union = ka | kb
    if not union:
        return 0.0
    return len(ka & kb) / len(union)

