def closest_pair_distance(points):
    n = len(points)
    best = None
    for i in range(n):
        for j in range(i + 1, n):
            d = ((points[i][0] - points[j][0]) ** 2 + (points[i][1] - points[j][1]) ** 2) ** 0.5
            if best is None or d < best:
                best = d
    return best

def is_rectangle_shape(p1, p2, p3, p4):
    def sq(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2
    def close(x, y):
        return abs(x - y) < 1e-9
    s1, s2, s3, s4 = sq(p1, p2), sq(p2, p3), sq(p3, p4), sq(p4, p1)
    d1, d2 = sq(p1, p3), sq(p2, p4)
    if s1 < 1e-9 or s2 < 1e-9:
        return False
    return close(s1, s3) and close(s2, s4) and close(d1, d2)

def farthest_pair_distance(points):
