        return []
    result = [lst[0]]
    for x in lst[1:]:
        if x != result[-1]:
            result.append(x)
    return result

def parse_query_string(qs):
    if qs == '':
        return {}
    result = {}
    for part in qs.split('&'):
        if '=' in part:
            k, v = part.split('=', 1)
        else:
            k, v = part, ''
        result[k] = v
    return result

