def dedupe_csv_list(s):
    seen = set()
    result = []
    for item in s.split(','):
        item = item.strip()
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def parse_temperature(s):
    unit = s[-1]
    value = float(s[:-1])
    if unit == 'F':
        return (value - 32) * 5 / 9
    return value

def parse_file_size(s):
    units = {'B': 1, 'KB': 1024, 'MB': 1024**2, 'GB': 1024**3}
    for unit in ('GB', 'MB', 'KB', 'B'):
        if s.endswith(unit):
            number = s[:-len(unit)]
            return float(number) * units[unit]

