        if e == "coin":
            state = "UNLOCKED"
        elif e == "push":
            if state == "UNLOCKED":
                state = "LOCKED"
    return state

def bank_balance_with_interest(events, rate):
    balance = 0
    for e in events:
        if e[0] == "deposit":
            balance += e[1]
        elif e[0] == "withdraw":
            if balance >= e[1]:
                balance -= e[1]
        elif e[0] == "month_end":
            balance = round(balance * (1 + rate), 2)
    return round(balance, 2)

def traffic_light_emergency(events):
    cycle = ["RED", "GREEN", "YELLOW"]
    idx = 0
    for e in events:
        if e == "tick":
            idx = (idx + 1) % 3
        elif e == "emergency":
            idx = 0
    return cycle[idx]

def longest_run(s):
    if not s:
        return ("", 0)
    best_char = s[0]
    best_len = 1
    cur_char = s[0]
    cur_len = 1
    for ch in s[1:]:
        if ch == cur_char:
            cur_len += 1
        else:
            cur_char = ch
            cur_len = 1
        if cur_len > best_len:
            best_len = cur_len
            best_char = cur_char
    return (best_char, best_len)

def can_become_palindrome_by_removing_one(s):
    def is_pal(sub):
        return sub == sub[::-1]
    l, r = 0, len(s) - 1
    while l < r:
        if s[l] != s[r]:
            return is_pal(s[l+1:r+1]) or is_pal(s[l:r])
        l += 1
        r -= 1
    return True

