def is_valid_sudoku_full_board(board):
    if len(board) != 9 or any(len(r) != 9 for r in board):
        return False
    for row in board:
        for v in row:
            if not isinstance(v, int) or v < 0 or v > 9:
                return False
    def ok(vals):
        nz = [v for v in vals if v != 0]
        return len(nz) == len(set(nz))
    for row in board:
        if not ok(row):
            return False
    for c in range(9):
        if not ok([board[r][c] for r in range(9)]):
            return False
    for br in range(0, 9, 3):
        for bc in range(0, 9, 3):
            box = [board[br+i][bc+j] for i in range(3) for j in range(3)]
            if not ok(box):
                return False
    return True

def is_valid_css_rgba_string(s):
    import re
    m = re.fullmatch(r'rgba\((\d{1,3}), (\d{1,3}), (\d{1,3}), (0|1|0\.\d)\)', s)
    if not m:
        return False
    for part in m.groups()[:3]:
        if len(part) > 1 and part[0] == '0':
            return False
        if int(part) > 255:
            return False
    return True
